                                continue
                            try:
                                end = dateutil_parser.parse(data['range']['end'])
                            except ValueError:
                                log.error('Invalid date string for end. Ignoring job %s.', job)
                                continue
                            if end > start:
                                if 'invert' in data['range'] and data['range']['invert']:
                                    if now <= start or now >= end:
