                if '_seconds' in data:
                    data['_next_fire_time'] = now + datetime.timedelta(seconds=data['_seconds'])
                data['_last_run'] = now
                data['_splay'] = None
            if salt.utils.platform.is_windows():
                # Restore our function references.
                self.functions = functions
                self.returners = returners

