                            tmp = int(dateutil_parser.parse(i).strftime('%s'))
                        except ValueError:
                            log.info('Invalid date string {0}.  Ignoring job {1}.'.format(i, job))
                            continue
                        if tmp >= now:
                            _when.append(tmp)
